class Solution:
    def numberOfRightTriangles(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        row = [sum(r) for r in grid]
        col = [sum(grid[i][j] for i in range(m)) for j in range(n)]
        ans = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j]:
                    ans += (row[i] - 1) * (col[j] - 1)
        return ans

